textColor:
{{
  (() => {
    const statut = (Get_Location_Detail.data[0]?.Statut || "").toUpperCase().trim();
    switch (statut) {
      case 'PIECE A COMMANDER':
      case 'PIÈCE À COMMANDER': return '#dc2626'; // Rouge
      case 'PIECE EN COMMANDE':
      case 'PIÈCE EN COMMANDE': return '#16a34a'; // Vert
      case 'DEVIS': return '#9333ea'; // Violet
      case 'A REMONTER':
      case 'À REMONTER': return '#ea580c'; // Orange / Rouge
      case 'À DIAGNOSTIQUER': return '#2563eb'; // Bleu
      case 'PRÊT': return '#15803d'; // Vert foncé
      default: return '#0f172a'; // Couleur texte sombre par défaut
    }
  })()
}}
